// Standard reducing-balance EMI.
export function emi(principal, annualRate, months) {
  const r = annualRate / 12 / 100;
  return (principal * r * (1 + r) ** months) / ((1 + r) ** months - 1);
}

const loans = {
  bajaj: { principal: 420000, rate: 16, newRate: 11.25, months: 34 },
  sbi: { principal: 3800000, rate: 8.9, newRate: 8.15, months: 216 },
};
const bajajNow = Math.round(emi(loans.bajaj.principal, loans.bajaj.rate, loans.bajaj.months));
const bajajNew = Math.round(emi(loans.bajaj.principal, loans.bajaj.newRate, loans.bajaj.months));
const sbiNow = Math.round(emi(loans.sbi.principal, loans.sbi.rate, loans.sbi.months));
const sbiNew = Math.round(emi(loans.sbi.principal, loans.sbi.newRate, loans.sbi.months));

